  ('cc685fef-47d7-5295-b5ca-63ea805dd4ad', null, (select id from public.skills where slug = 'read-g12-comparing-texts'), null, 'hard',
   $q$Which statement best compares what each text values about the slow runner's effort?$q$, $q$[{"text":"Both texts value speed above all and treat finishing late as a kind of failure.","is_correct":false,"misconception_token":"reverses-meaning"},{"text":"Text 1 values the cheering crowd, while Text 2 values the runner's eight months of training.","is_correct":false,"misconception_token":"confuses-texts"},{"text":"Text 1 values the private promise the runner keeps to himself, while Text 2 values witnessing and honoring that effort from outside.","is_correct":true},{"text":"Text 1 values the medal the runner earns, while Text 2 values the record time printed in the paper.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$Text 1 values the private promise the runner keeps to himself, while Text 2 values witnessing and honoring that effort from outside.$q$, $q$Femi runs to "keep a promise to himself," an inward reason, while the poem's speaker wants to "be the cheer they did not hear," an outside witness. The poem says "There is no prize for this," so medals and records are not what it values.$q$, 'draft', '0ffe9028-d76f-5540-8d17-2fe7e203e06b')
